class Solution:
    def widestPairOfIndices(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        best = 0
        for i in range(n):
            s1 = s2 = 0
            for j in range(i, n):
                s1 += nums1[j]
                s2 += nums2[j]
                if s1 == s2:
                    best = max(best, j - i + 1)
        return best

