class Solution {
public:
    int widestPairOfIndices(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> first;
        first[0] = -1;
        int d = 0, ans = 0;
        for (int i = 0; i < (int)nums1.size(); ++i) {
            d += nums1[i] - nums2[i];
            auto it = first.find(d);
            if (it != first.end()) ans = max(ans, i - it->second);
            else first[d] = i;
        }
        return ans;
    }
};

