class Solution {
    public int widestPairOfIndices(int[] nums1, int[] nums2) {
        Map<Integer, Integer> first = new HashMap<>();
        first.put(0, -1);
        int d = 0, ans = 0;
        for (int i = 0; i < nums1.length; ++i) {
            d += nums1[i] - nums2[i];
            Integer seen = first.get(d);
            if (seen != null) ans = Math.max(ans, i - seen);
            else first.put(d, i);
        }
        return ans;
    }
};

